<form class="card max-w-4xl space-y-5 p-6" method="post" action="<?=url('receivables/save')?>"><?=csrf_field()?><input type="hidden" name="id" value="<?=e($item['id'])?>"><div class="grid gap-4 sm:grid-cols-2"><label class="sm:col-span-2"><span class="label">Descrição</span><input class="field" name="description" value="<?=e($item['description'])?>" required></label><label><span class="label">Cliente</span><select class="field" name="contact_id"><option value="">Selecione</option><?php foreach($contacts as $o):?><option value="<?=$o['id']?>" <?=$item['contact_id']==$o['id']?'selected':''?>><?=e($o['name'])?></option><?php endforeach;?></select></label><label><span class="label">Categoria</span><select class="field" name="category_id"><option value="">Selecione</option><?php foreach($categories as $o):?><option value="<?=$o['id']?>" <?=$item['category_id']==$o['id']?'selected':''?>><?=e($o['name'])?></option><?php endforeach;?></select></label><label><span class="label">Valor esperado</span><input class="field" name="expected_amount" inputmode="decimal" value="<?=e($item['expected_amount'])?>" placeholder="0,00" required></label><label><span class="label">Data de vencimento</span><input class="field" type="date" name="due_date" value="<?=e($item['due_date'])?>" required></label><label><span class="label">Forma de recebimento</span><select class="field" name="receipt_method"><?php foreach(['pix'=>'Pix','cartao_credito'=>'Cartão crédito','cartao_debito'=>'Cartão débito','boleto'=>'Boleto','dinheiro'=>'Dinheiro','transferencia'=>'Transferência'] as $v=>$l):?><option value="<?=$v?>" <?=$item['receipt_method']===$v?'selected':''?>><?=$l?></option><?php endforeach;?></select></label><label class="sm:col-span-2"><span class="label">Observações</span><textarea class="field" name="notes" rows="4"><?=e($item['notes'])?></textarea></label></div><div class="flex gap-3"><button class="btn btn-primary">Salvar</button><a class="btn btn-light" href="<?=url('receivables')?>">Cancelar</a></div></form>
